async function main() {
  let countryCreated = 0, countrySkipped = 0;
  let cityCreated = 0, citySkipped = 0;
  const countryMap = {};
  const countryRegionMap = {};

  for (const c of COUNTRIES) {
    const exists = await prisma.country.findFirst({ where: { slug: c.slug } });
    if (exists) { countrySkipped++; countryMap[c.slug] = exists.id; countryRegionMap[c.slug] = exists.region; continue; }
    const created = await prisma.country.create({ data: c });
    countryMap[c.slug] = created.id;
    countryRegionMap[c.slug] = c.region;
    countryCreated++;
    console.log('Country: ' + c.name);
  }

  for (const city of CITIES) {
    const { country, tags, ...data } = city;
    const countryId = countryMap[country];
    if (!countryId) { console.log('SKIP (no country): ' + city.name); continue; }
    const exists = await prisma.city.findFirst({ where: { slug: data.slug } });
    if (exists) { citySkipped++; process.stdout.write('.'); continue; }
    const region = countryRegionMap[country];
    await prisma.city.create({ data: { ...data, countryId, region, tags: { create: tags.map(t => ({ tag: t })) } } });
    cityCreated++;
    console.log('City: ' + data.name);
  }

  console.log('\nDone: countries created=' + countryCreated + ' skipped=' + countrySkipped);
  console.log('Cities created=' + cityCreated + ' skipped=' + citySkipped);
  await prisma.$disconnect();
}

main().catch(e => { console.error(e.message); process.exit(1); });
